// Mapear campos del Form a estructura esperada
const timestamp = items[0].json['Timestamp'] || new Date().toISOString();
const email = items[0].json['Email'];
const nombre = items[0].json['Nombre completo'];
const telefono = items[0].json['Teléfono (formato internacional +34...)'];
const p1_expertise = items[0].json['¿En qué eres experto/a? ¿Qué habilidad o conocimiento dominas?'];
const p2_resultado = items[0].json['¿Qué resultado específico quieres ayudar a lograr a tus clientes?'];
const p3_target = items[0].json['¿Quién es tu cliente ideal? Sé lo más específico posible (edad, profesión, situación, etc.)'];
const p4_transformaciones = items[0].json['¿Qué transformaciones has logrado con clientes anteriores? (menciona números, tiempos, resultados concretos)'];

// Detectar país desde código telefónico
const countryCodeMap = {
  '1': 'Estados Unidos/Canadá',
  '34': 'España',
  '52': 'México',
  '54': 'Argentina',
  '55': 'Brasil',
  '56': 'Chile',
  '57': 'Colombia',
  '58': 'Venezuela',
  '351': 'Portugal',
  '51': 'Perú',
  '33': 'Francia'
};

let pais = 'Desconocido';
if (telefono && telefono.startsWith('+')) {
  const phoneNumber = telefono.substring(1);
  for (let len = 3; len >= 1; len--) {
    const code = phoneNumber.substring(0, len);
    if (countryCodeMap[code]) {
      pais = countryCodeMap[code];
      break;
    }
  }
}

return [{
  json: {
    timestamp,
    email,
    nombre,
    telefono,
    pais,
    p1_expertise,
    p2_resultado,
    p3_target,
    p4_transformaciones
  }
}];

// Separar los 3 outputs de Claude
const fullResponse = items[0].json.response || items[0].json.output || items[0].json.text;
const outputs = fullResponse.split('###OUTPUT_SEPARATOR###');

const output1 = outputs[0] ? outputs[0].trim() : '';
const output2 = outputs[1] ? outputs[1].trim() : '';
const output3 = outputs[2] ? outputs[2].trim() : '';

return items.map(item => ({
  json: {
    ...item.json,
    cliente_ideal: output1,
    mision_transformacional: output2,
    metodo_unico: output3
  }
}));
